package dev.mlua.modules.coregui;

import dev.mlua.core.service.MLuaService;
import dev.mlua.modules.coregui.service.MLuaGuiService;
import dev.mlua.module.MLuaDocBuilder;
import dev.mlua.module.MLuaModule;
import dev.mlua.common.enums.Side;
import java.util.List;

@dev.mlua.module.MLuaModuleSide(Side.CLIENT)
public class GuiModule implements MLuaModule {
    @Override
    public void clearRuntimeState(dev.mlua.module.MLuaRegistration runtime, Object runtimeSession, Side side) {
        if (side == Side.CLIENT || side == Side.BOTH) {
            dev.mlua.core.MLuaRuntimeSession session = (dev.mlua.core.MLuaRuntimeSession) runtimeSession;
            MLuaGuiService.clearForScheduler(session.clientScheduler());
            dev.mlua.minecraft.binding.MLuaNativeControl.invalidateRuntime(session);
        }
    }

    @Override
    public void clearOwnedState(dev.mlua.module.MLuaRegistration runtime, Object runtimeSession, Side side, String ownerModId) {
        if (side == Side.CLIENT || side == Side.BOTH) {
            dev.mlua.core.MLuaRuntimeSession session = (dev.mlua.core.MLuaRuntimeSession) runtimeSession;
            MLuaGuiService gui = MLuaGuiService.getForScheduler(session.clientScheduler());
            if (gui != null) gui.clearOwned(ownerModId);
            dev.mlua.minecraft.binding.MLuaNativeControl.invalidateOwner(session, ownerModId);
        }
    }

    @Override
    public String id() { return "gui"; }

    @Override
    public Side side() { return Side.CLIENT; }

    @Override
    public List<ServiceEntry> services() {
        ServiceEntry.Builder gui = ServiceEntry.builder("Gui", MLuaGuiService::new)
            .description("Manages live UI instances, screen overlays, native Minecraft controls, and callbacks around vanilla HUD and chat rendering. ScreenOpened and ScreenClosed supply the screen class name, native controls, and a NativeScreen handle; ChatLineAdding supplies a short-lived ChatLine whose Text, Prefix, and Suffix can be changed before Minecraft stores the message.");
        gui.function("GetEnabled", "Returns whether MLua GUI overlays are enabled.")
            .function("SetEnabled", "Enables or disables all MLua GUI overlays.")
            .function("GetScreens", "Returns live ScreenGui instances attached to the overlay.")
            .function("CreateScreen", "Creates and attaches a ScreenGui; parent UIObject instances to it to compose a screen.")
            .function("OpenNativeScreen", "Opens a real Minecraft Screen with a string or Java Component title. The call returns a NativeScreen handle immediately; IsPending stays true until Minecraft runs the screen's init callback on its client loop. IsOpen and native control inspection or mutation must run on the client thread, such as inside screen lifecycle callbacks. Its init callback receives AddText, AddButton, AddEditBox, AddRenderableWidget, SetOnClose, SetOnTick, and SetOnRender. AddRenderableWidget accepts Java-created Minecraft widgets; all widget methods return live NativeControl instances. Positions and sizes use UDim2.")
            .function("OpenScreen", "Creates a registered Screen subclass with a string or Java Component title. Its Init method runs during Minecraft's screen init lifecycle; use AddRenderableWidget for Java-created widgets.")
            .function("CloseCurrentScreen", "Closes the currently active Minecraft screen, including vanilla screens; returns false when no screen is open. The change is queued when called from a Lua worker.")
            .function("RemoveScreen", "Removes and destroys the first screen matching an instance or name.")
            .function("SetCoreGuiEnabled", "Shows or hides MLua overlays associated with a CoreGuiType channel.")
            .function("GetCoreGuiEnabled", "Returns whether MLua overlays associated with a CoreGuiType channel are enabled.")
            .function("AddScreenGui", "Adds a live ScreenGui instance or builds one from a definition table; Children must be a dense array so draw order matches the list, and child __type names resolve against the calling addon's registered UI classes.")
            .function("RemoveScreenGui", "Removes and destroys a ScreenGui by instance or name, returning whether one was removed.")
            .function("GetScreenGuis", "Returns live ScreenGui instances attached to the active overlay.")
            .function("GetCoreGui", "Returns the shared MLua ScreenGui overlay for a CoreGuiType channel, or nil if none exists.")
            .function("CreateCoreGui", "Gets or creates a shared MLua ScreenGui overlay associated with one CoreGuiType channel.")
            .function("RegisterScreenTarget", "Registers an addon-owned screen alias that matches a Minecraft screen class or interface and can be used by ScreenGui.TargetScreen and SetNativeLayout.")
            .function("UnregisterScreenTarget", "Removes this addon's screen alias and stops it from matching overlays or native layout rules.")
            .function("GetNativeControls", "Returns live NativeControl instances for widgets on the currently open Minecraft screen. Call on the client thread. Selectors can match one-based Index, a Java class or interface by simple or fully qualified name, Text, or any readable public bean property with a string, number, or boolean value.")
            .function("GetNativeControl", "Returns the first live NativeControl matching Index, a Java class or interface, Text, or a readable public bean property on the current screen. Call on the client thread.")
            .function("SetNativeLayout", "Registers a bulk layout rule and applies it to the current screen immediately when it matches. Call on the client thread. Class selectors include subclasses and implemented interfaces; property selectors compare readable public bean properties. Position and Size require native UDim2 values; Visible, Text, Replacement, Before, and After are supported, along with additional public bean properties whose setters accept supported Lua values. Before and After require an Index selector.")
            .function("RemoveNativeLayout", "Removes a native widget layout rule by its returned identifier. Call on the client thread.")
            .function("AttachElementBefore", "Attaches a Lua draw callback before a VanillaHudElements anchor. Each invocation receives a frame-scoped canvas with Width, Height, Anchor, Phase, Fill, and DrawText; drawing methods expire when the callback returns and must run on the render thread. Each callback is limited to 100,000 interpreted Lua instructions; a callback that errors or exceeds the limit is disabled until registered again. Optional whole-number priority orders callbacks; higher values draw later. Registering the same addon id replaces its previous callback.")
            .function("AttachElementAfter", "Attaches a Lua draw callback after a VanillaHudElements anchor. Each invocation receives a frame-scoped canvas with Width, Height, Anchor, Phase, Fill, and DrawText; drawing methods expire when the callback returns and must run on the render thread. Each callback is limited to 100,000 interpreted Lua instructions; a callback that errors or exceeds the limit is disabled until registered again. Optional whole-number priority orders callbacks; higher values draw later. Registering the same addon id replaces its previous callback.")
            .function("RemoveHudElement", "Removes this addon's HUD callback by its local id.");
        return List.of(gui.build());
    }

    @Override
    public void contributeDocs(MLuaDocBuilder docs) {
        docs.register(MLuaDocBuilder.Registration.signature("Gui", "Gui:OpenNativeScreen(title: string|Component, initialize: function): NativeScreen", "Opens a screen and runs its native widget initialization callback."));
        docs.register(MLuaDocBuilder.Registration.signature("Gui", "Gui:OpenScreen(className: string, title: string|Component, fields?: table): Screen", "Creates a registered Screen subclass and opens it."));
        docs.register(MLuaDocBuilder.Registration.method("Gui", "Gui:CloseCurrentScreen()", "Closes the active Minecraft screen, including vanilla screens. Returns false if no screen is open; calls from Lua workers queue the close on Minecraft's client thread.", null, "boolean", "client:Client", null));
        docs.register(MLuaDocBuilder.Registration.service("Gui", "MLuaGuiService",
                "Manages live UI instances, screen overlays, native Minecraft controls, and callbacks around the full HUD or chat render anchors. Native screens expose Minecraft's init, tick, render, and close lifecycle. A queued open is applied by the client loop once the Minecraft window is available; native widget reads and writes run on the client thread, while queued open and close requests may come from Lua workers. ScreenOpened and ScreenClosed supply the screen class name, live NativeControl instances, and a NativeScreen handle; ChatLineAdding supplies a short-lived ChatLine whose Text, Prefix, and Suffix can be changed before Minecraft stores the message.",
                "services/gui.html"));
        docs.register(MLuaDocBuilder.Registration.event("Gui", "Gui.ScreenOpened", "screenClass: string, controls: NativeControl[], screen: NativeScreen",
                "Fires after Minecraft creates a screen's widgets. The third argument is a live NativeScreen instance; check CanInspectControls when an empty controls list could mean the screen does not expose Minecraft's standard child-widget API.", "client:Client"));
        docs.register(MLuaDocBuilder.Registration.event("Gui", "Gui.ScreenClosed", "screenClass: string, controls: NativeControl[], screen: NativeScreen",
                "Fires when Minecraft removes a screen. The NativeScreen reports IsOpen as false. The controls remain inspectable during the synchronous part of this callback for final reads; they become stale after the callback returns. Native widget layout changes are restored before listeners run.", "client:Client"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Build a native Minecraft screen",
                "OpenNativeScreen creates and opens a real Minecraft Screen. Its callback runs during the screen's init lifecycle. AddText draws through Minecraft's screen graphics callback; AddButton and AddEditBox add common native controls. AddRenderableWidget accepts a widget created through Java interop, such as a Button built with Minecraft's own builder. These methods return live NativeControl instances, and the returned NativeScreen can inspect controls and close the screen.",
                "local Gui = Minecraft:GetService(\"Gui\")\nlocal Java = Minecraft:GetService(\"Java\")\nlocal Component = Java:LoadClass(\"net.minecraft.network.chat.Component\")\n\nlocal screen = Gui:OpenNativeScreen(\"Radio Console\", function(screen)\n    screen:AddText(Component.literal(\"Emergency channel\"), UDim2.fromOffset(40, 32), 0xFFFFFF)\n    screen:AddButton(Component.literal(\"Tune\"), UDim2.fromOffset(40, 60), UDim2.fromOffset(120, 20), function(button)\n        print(\"Radio tuned from widget\", button.Index)\n    end)\n    local station = screen:AddEditBox(UDim2.fromOffset(40, 92), UDim2.fromOffset(160, 20), \"station-01\", function(text, field)\n        print(\"Station changed to\", text)\n    end)\n    print(station.Value)\n    screen:SetOnClose(function()\n        print(\"Radio console closed\")\n    end)\nend)\n\nprint(screen.IsOpen)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Update screen logic on Minecraft ticks",
                "SetOnTick runs once per Minecraft client screen tick, separate from SetOnRender's per-frame callback. Keep world or render timing calculations in their matching lifecycle callbacks. If a tick callback raises an error, MLua logs it and pauses that callback for this screen.",
                "local Gui = Minecraft:GetService(\"Gui\")\nlocal elapsedTicks = 0\n\nGui:OpenNativeScreen(\"Signal Monitor\", function(screen)\n    screen:SetOnTick(function()\n        elapsedTicks = elapsedTicks + 1\n    end)\n    screen:SetOnRender(function(canvas)\n        canvas:DrawText(\"Ticks open: \" .. elapsedTicks, 20, 20, 0xFFFFFF, true)\n    end)\nend)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Draw during the native screen render lifecycle",
                "SetOnRender runs after Minecraft renders the screen and its native widgets. The canvas exposes Minecraft's current screen graphics through Fill and DrawText and reports the current screen Width and Height. Coordinates are whole-number pixels; colors accept 24-bit RGB or 32-bit ARGB values. DrawText accepts a string or Java Component, so styled Minecraft text can be preserved.",
                "local Gui = Minecraft:GetService(\"Gui\")\nGui:OpenNativeScreen(\"Signal Monitor\", function(screen)\n    screen:SetOnRender(function(canvas, mouseX, mouseY, delta)\n        canvas:Fill(20, 20, 220, 58, 0xFF101820)\n        canvas:DrawText(\"SIGNAL DETECTED\", 28, 28, 0xFFFFFF, true)\n        canvas:DrawText(\"Pointer: \" .. mouseX .. \", \" .. mouseY, 28, 40, 0xFF88CCFF, false)\n    end)\nend)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Extend the native Screen class",
                "Register a subclass of Screen and add native widgets from Init. Gui:OpenScreen constructs the registered class, installs native widget methods, then runs Init during the actual Minecraft Screen init callback. KeyPressed, KeyReleased, CharTyped, MouseClicked, MouseReleased, MouseDragged, MouseMoved, and MouseScrolled run before Minecraft's handlers; return true to consume an input event and false or nil to keep normal screen behavior. MouseMoved is observational and its return value is ignored. Define IsPauseScreen to return false for screens that should leave the world running, or ShouldCloseOnEsc to override Escape handling. OnFilesDrop receives a one-based array of dropped path strings, then Minecraft's normal screen handler runs. Character modifier data is zero on Minecraft 26.1 because CharacterEvent does not include it.",
                "Minecraft:RegisterClass(\"RadioScreen\", \"Screen\", \"A radio tuning screen.\")\nMinecraft:RegisterClassFunction(\"RadioScreen\", \"IsPauseScreen\", function(self)\n    return false -- Keep the world running while the radio is open.\nend, \"Leaves the world active behind this screen.\")\nMinecraft:RegisterClassFunction(\"RadioScreen\", \"Init\", function(self)\n    self:AddText(\"Emergency channel\", UDim2.fromOffset(40, 32), 0xFFFFFF)\n    self:AddButton(\"Tune\", UDim2.fromOffset(40, 60), UDim2.fromOffset(120, 20), function(button)\n        print(\"Radio tuned from widget\", button.Index)\n    end)\nend, \"Builds the native radio screen widgets.\")\nMinecraft:RegisterClassFunction(\"RadioScreen\", \"KeyPressed\", function(self, keyCode, scanCode, modifiers)\n    if keyCode == 256 then -- Escape\n        self:Close()\n        return true\n    end\n    return false\nend, \"Closes the radio screen on Escape.\")\nMinecraft:RegisterClassFunction(\"RadioScreen\", \"OnFilesDrop\", function(self, paths)\n    for _, path in ipairs(paths) do\n        print(\"Dropped onto radio screen:\", path)\n    end\nend, \"Reports files dropped on the screen.\")\nMinecraft:RegisterClassFunction(\"RadioScreen\", \"Render\", function(self, canvas, mouseX, mouseY, delta)\n    canvas:Fill(40, 96, 240, 120, 0xFF18202A)\n    canvas:DrawText(\"Pointer: \" .. mouseX .. \", \" .. mouseY, 48, 100, 0xFF88CCFF, false)\nend, \"Draws live status during Minecraft's screen render lifecycle.\")\n\nlocal Gui = Minecraft:GetService(\"Gui\")\nlocal screen = Gui:OpenScreen(\"RadioScreen\", \"Radio Console\")"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Use Minecraft's widget builder from a Lua Screen",
                "A Lua Screen subclass can add a Minecraft AbstractWidget returned by Java:New or a Java method. Build it with Minecraft's own classes and callback interface, then pass it to AddRenderableWidget. The result is a NativeControl tied to the live screen.",
                "local Java = Minecraft:GetService(\"Java\")\nlocal Button = Java:LoadClass(\"net.minecraft.client.gui.components.Button\")\nlocal Component = Java:LoadClass(\"net.minecraft.network.chat.Component\")\nlocal onPress = Java:Proxy(Button.OnPress, {\n    onPress = function(button)\n        print(\"Hello from a native Minecraft button\")\n    end\n})\n\nMinecraft:RegisterClassFunction(\"RadioScreen\", \"Init\", function(self)\n    local button = Button.builder(Component.literal(\"Hello World\"), onPress)\n        :bounds(40, 40, 120, 20)\n        :build()\n    local control = self:AddRenderableWidget(button)\n    print(control.WidgetClass)\nend, \"Builds and attaches a native Minecraft button.\")"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Build a screen from live UI instances",
                "Create a ScreenGui, then parent normal UIObject instances into it. The instances use inherited properties and signals, so a TextButton can be composed inside a Frame like any other GuiObject.",
            "local Gui = Minecraft:GetService(\"Gui\")\nlocal screen = Gui:CreateScreen(\"HorrorHUD\", { DisplayOrder = 20 })\nlocal panel = UIObject.new(\"Frame\", \"FearPanel\")\nlocal title = UIObject.new(\"TextLabel\", \"Title\")\nlocal button = UIObject.new(\"TextButton\", \"StartButton\")\n\npanel.Size = UDim2.fromOffset(220, 110)\ntitle.Text = \"Something is nearby\"\nbutton.Text = \"Hide\"\nbutton.Activated:Connect(function()\n    print(\"Hide button activated\")\nend)\n\ntitle.Parent = panel\nbutton.Parent = panel\npanel.Parent = screen"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Handle pointer input on UI objects",
                "InputBegan and InputEnded fire for the object that received a mouse press. InputChanged and MouseMoved fire when the pointer moves over it; MouseWheelForward and MouseWheelBackward fire while scrolling over it. The event table includes UserInputType and Position.X/Position.Y; wheel events also include WheelDelta.",
                "local button = UIObject.new(\"TextButton\", \"InspectButton\")\nbutton.Text = \"Inspect\"\n\nbutton.InputBegan:Connect(function(input)\n    if input.UserInputType == \"MouseButton1\" then\n        print(\"Press at\", input.Position.X, input.Position.Y)\n    end\nend)\n\nbutton.Activated:Connect(function()\n    print(\"Released on the button\")\nend)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Extend a UI class for an addon",
                "Register an addon class with a UI parent such as Frame. It inherits the parent's native constructor, properties, and methods. UIObject.new passes the selected class as self, so the inherited constructor creates a live native-backed instance of your subclass. Initial properties are applied before Init methods run from base class to subclass, once per class level; use RegisterClassFunction for each class method and include its description at registration.",
                "local FearPanel = Minecraft:RegisterClass(\"FearPanel\", \"Frame\", \"A reusable panel for horror warnings.\")\n\nMinecraft:RegisterClassFunction(\"FearPanel\", \"Init\", function(self, fields)\n    self.Size = fields.Size or UDim2.fromOffset(220, 80)\nend, \"Applies the initial size to a warning panel.\")\n\nMinecraft:RegisterClassFunction(\"FearPanel\", \"SetWarning\", function(self, text)\n    local label = self:FindFirstChild(\"Warning\")\n    if label then\n        label.Text = text\n    end\nend, \"Updates the panel's Warning label when it exists.\")\n\nlocal panel = UIObject.new(\"FearPanel\", \"WarningPanel\", {\n    Size = UDim2.fromOffset(260, 100),\n})\nlocal label = UIObject.new(\"TextLabel\", \"Warning\")\nlabel.Parent = panel\npanel:SetWarning(\"Something is behind you\")"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Change player chat lines",
                "ChatLineAdding runs before Minecraft stores each chat line. ChatLine is a short-lived live instance: OriginalText lets you inspect the input, Modified shows whether any addon changed it, Prefix and Suffix preserve the original formatting, and Text accepts either literal text or a Java Component so rich formatting can be retained.",
                "local Gui = Minecraft:GetService(\"Gui\")\nlocal Java = Minecraft:GetService(\"Java\")\nlocal Component = Java:LoadClass(\"net.minecraft.network.chat.Component\")\n\nGui.ChatLineAdding:Connect(function(line)\n    if line.OriginalText:find(\"emergency\") then\n        line.Text = Component.literal(\"[RADIO] Emergency call\")\n    else\n        line.Prefix = \"[RADIO] \"\n    end\n    if line.Modified then\n        print(\"An earlier listener changed this message\")\n    end\nend)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Draw relative to native HUD anchors",
                "AttachElementBefore and AttachElementAfter accept Hud, Chat, Crosshair, Hotbar, Health, Experience, Effects, Food, OverlayMessage, Title, Scoreboard, or PlayerList. Minecraft-version-specific anchors run where that native render method exists: Effects is available on all supported versions, Food on 1.21.1, and OverlayMessage, Title, Scoreboard, and PlayerList on 1.21.1 and 26.1. Each callback receives a fresh frame-scoped canvas. Width and Height report scaled screen dimensions, Anchor names the active vanilla element, and Phase is Before or After. Fill and DrawText work only during that callback on the render thread; retaining the canvas does not retain access to Minecraft's graphics object. Pass an optional whole-number priority after the callback; lower values draw first and higher values draw later, with registration order resolving ties. Fill takes whole-number pixel boundaries (left, top, right, bottom) and a 24-bit RGB or 32-bit ARGB color; DrawText takes a string or Java Component, whole-number x and y pixels, an RGB or ARGB color, and an optional shadow flag. Registering the same local id replaces its callback, and RemoveHudElement removes it.",
                "local Gui = Minecraft:GetService(\"Gui\")\nlocal Hud = Gui.VanillaHudElements\nlocal Java = Minecraft:GetService(\"Java\")\nlocal Component = Java:LoadClass(\"net.minecraft.network.chat.Component\")\n\nlocal function drawBadge(canvas)\n    canvas:Fill(8, 8, 92, 28, 0xCC101820)\n    canvas:DrawText(Component.literal(\"RADIO\"), 16, 14, 0xFFFFFF, true)\nend\n\nGui:AttachElementBefore(Hud.Chat, \"radio_chat_badge\", drawBadge)\nGui:AttachElementAfter(Hud.Hud, \"radio_hud_badge\", drawBadge)\nGui:AttachElementAfter(Hud.Crosshair, \"radio_aim_dot\", drawBadge)\nGui:AttachElementBefore(Hud.Hotbar, \"radio_hotbar_label\", drawBadge)\nGui:AttachElementAfter(Hud.Health, \"radio_vitals\", drawBadge)\nGui:AttachElementAfter(Hud.Effects, \"radio_effects\", drawBadge)\nGui:AttachElementAfter(Hud.PlayerList, \"radio_players\", drawBadge, 5)\nGui:AttachElementBefore(Hud.Title, \"radio_title\", drawBadge, 10)\nGui:RemoveHudElement(\"radio_chat_badge\")"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Add content beside a native control",
                "ScreenOpened provides the screen class name, its live NativeControl instances, and a live NativeScreen. Check CanInspectControls before treating an empty list as a screen with no widgets. Find a widget by its Java class instead of relying on a version-specific list position, then place addon UI beside it with Before or After.",
                "local Gui = Minecraft:GetService(\"Gui\")\n\nGui.ScreenOpened:Connect(function(screenClass, controls, screen)\n    if screenClass:find(\"ChatScreen\") then\n        local inputs = screen:FindControls(\"EditBox\")\n        local chatInput = inputs[1]\n        if chatInput then\n            local badge = UIObject.new(\"TextLabel\", \"RadioBadge\")\n            badge.Text = \"RADIO\"\n            badge.Size = UDim2.fromOffset(60, 20)\n            chatInput.Before = badge\n            print(chatInput.WidgetClass, screen.IsOpen, #controls)\n        end\n    end\nend)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Reposition a native control",
                "Use a native UDim2 for both dimensions in a layout rule. The rule applies to matching widgets when screens open and can be removed by its returned id.",
                "local Gui = Minecraft:GetService(\"Gui\")\nlocal layoutId = Gui:SetNativeLayout(\"ChatScreen\", { Index = 1 }, {\n    Position = UDim2.fromOffset(24, 24),\n    Size = UDim2.new(1, -48, 0, 22),\n})\n\nprint(\"Active layout\", layoutId)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Target screens by class",
                "Set ScreenGui.TargetScreen to a Minecraft screen class name. MLua matches the concrete screen, its superclasses, and its interfaces, so custom screens can target a stable base class instead of a version-specific subclass name.",
                "local Gui = Minecraft:GetService(\"Gui\")\nlocal overlay = Gui:CreateScreen(\"ContainerTools\", { TargetScreen = \"AbstractContainerScreen\", RenderLayer = \"After\" })\nlocal panel = UIObject.new(\"Frame\", \"ContainerPanel\")\npanel.Parent = overlay"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Register a screen alias for an addon screen",
                "Register an addon-owned alias once, then use it from ScreenGui.TargetScreen or SetNativeLayout. The alias matches the named Java class, its superclasses, and its interfaces, and is removed when the registering addon reloads.",
                "local Gui = Minecraft:GetService(\"Gui\")\nGui:RegisterScreenTarget(\"MyModJournal\", \"com.example.mymod.JournalScreen\")\n\nlocal overlay = Gui:CreateScreen(\"JournalOverlay\", { TargetScreen = \"MyModJournal\" })\nlocal panel = UIObject.new(\"Frame\", \"JournalPanel\")\npanel.Parent = overlay"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Read additional native widget properties",
                "NativeControl exposes common properties directly. For other public widget properties, GetProperty and SetProperty find matching getX/isX/setX methods at runtime. Use those same readable values in selectors to find a control without relying on its index. Property access supports strings, numbers, booleans, enum names, and text components; unsupported Java property types produce an error.",
                "local Gui = Minecraft:GetService(\"Gui\")\n\nlocal input = Gui:GetNativeControl({ Class = \"EditBox\", Value = \"\" })\nif input then\n    input:SetProperty(\"Value\", \"radio channel open\")\nend"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Call a native widget method",
                "NativeControl:GetMethods lists the public methods on a live Minecraft widget. Invoke calls a method when MLua can convert its arguments; it returns supported strings, numbers, booleans, enum names, or text values, and returns nil for other Java result types.",
                "Gui.ScreenOpened:Connect(function(screenClass, controls)\n    local input = controls[1]\n    if not input then return end\n\n    for _, signature in ipairs(input:GetMethods()) do\n        print(signature)\n    end\n\n    input:Invoke(\"setMessage\", \"radio channel open\")\nend)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Gui", "Persist another native widget property",
                "SetNativeLayout accepts additional public bean properties when their setters accept a string, number, boolean, enum name, or text value. The property must also have a public getter so MLua can restore the original value when the layout is removed.",
                "local Gui = Minecraft:GetService(\"Gui\")\n\nlocal layoutId = Gui:SetNativeLayout(\"ChatScreen\", { Index = 1 }, {\n    Value = \"radio channel open\"\n})"));
    }
}
